-- ============================================================================
-- ORIGIN — Seed: 237 real Cameroon tourism / heritage sites (idempotent)
-- ----------------------------------------------------------------------------
-- Researched from public web sources. image_url = REAL free Wikipedia /
-- Wikimedia lead image when the site has one (114/237 sites). The web app
-- shows a clean on-brand placeholder for the rest — NEVER a random/unrelated image.
-- Self-sufficient (adds the image_url column) + idempotent. Run in Supabase SQL Editor.
-- ============================================================================

ALTER TABLE "tourism_places" ADD COLUMN IF NOT EXISTS "image_url" VARCHAR(500);

