  ('Mont Fébé', 'Colline boisée dominant Yaoundé, offrant panoramas, golf et fraîcheur au-dessus de la ville aux sept collines.', 'Centre', 'NATURE', 3.905, 11.507, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/V%C3%A9g%C3%A9tation_sur_le_Mont_F%C3%A9b%C3%A9.jpg/960px-V%C3%A9g%C3%A9tation_sur_le_Mont_F%C3%A9b%C3%A9.jpg'),
  ('Lac municipal de Yaoundé', 'Plan d''eau paisible au centre de la capitale, lieu de promenade et de détente prisé des Yaoundéens.', 'Centre', 'NATURE', 3.865, 11.513, NULL),
