  ('Lolodorf', 'Bourgade pittoresque blottie dans la forêt, Lolodorf est une fenêtre sur la culture des peuples pygmées Bagyeli du sud.', 'Sud', 'CULTURE', 3.23, 10.73, NULL),
  ('Bipindi', 'Au cœur de la forêt entre Kribi et Lolodorf, Bipindi invite à la rencontre des campements pygmées Bagyeli et de leurs savoirs ancestraux.', 'Sud', 'CULTURE', 3.08, 10.42, 'https://upload.wikimedia.org/wikipedia/commons/d/d3/Bipindi_3828587.png'),
  ('Grottes et python sacré d''Akok', 'Lieux légendaires du pays sud, les grottes d''Akok Bekoué et le mythique python d''Akok''okas nourrissent récits et croyances ancestrales.', 'Sud', 'HERITAGE', 2.95, 11.2, NULL),
  ('Ambam', 'Carrefour des trois frontières Cameroun-Gabon-Guinée équatoriale, Ambam vibre du métissage culturel du grand sud forestier.', 'Sud', 'OTHER', 2.383, 11.283, NULL),
