  ('Chefferie traditionnelle de Batouri', 'Au pays Kako, la chefferie de Batouri dévoile regalia, autorité coutumière et cérémonies colorées au rythme du grand marché.', 'Est', 'CHEFFERIE', 4.433, 14.367, NULL),
  ('Yokadouma', 'Dernière grande ville avant la forêt profonde, Yokadouma est le point de départ vers les parcs du sud-est et les communautés Baka.', 'Est', 'CULTURE', 3.52, 15.05, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Route_de_Yokadouma.jpg/960px-Route_de_Yokadouma.jpg'),
  ('Abong-Mbang', 'Posée sur le haut Nyong, Abong-Mbang séduit par son fleuve majestueux, son artisanat du bois et son ambiance de cité forestière.', 'Est', 'OTHER', 3.983, 13.183, NULL),
