  ('Villages Baka du sud-est', 'Au fil des pistes forestières, les campements du peuple Baka partagent chants polyphoniques, pharmacopée et savoir-faire des chasseurs-cueilleurs.', 'Est', 'CULTURE', 3.2, 14, 'https://upload.wikimedia.org/wikipedia/commons/5/54/Baka_dancers_June_2006.jpg'),
  ('Garoua-Boulaï', 'Ville-frontière vibrante aux portes de la Centrafrique, Garoua-Boulaï est un carrefour de routes, de peuples et de commerce de l''Est.', 'Est', 'OTHER', 5.88, 14.55, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Mosqu%C3%A9e_%2828604170443%29.jpg/960px-Mosqu%C3%A9e_%2828604170443%29.jpg'),
  ('Bétaré-Oya', 'Cité aurifère légendaire, Bétaré-Oya raconte l''épopée des chercheurs d''or au milieu des collines et des rivières de l''Est.', 'Est', 'OTHER', 5.6, 14.08, NULL),
