  ('Forêt communale de Dimako', 'Modèle pionnier de gestion forestière communautaire, Dimako invite à découvrir la forêt de l''Est sur ses sentiers d''écotourisme.', 'Est', 'NATURE', 4.38, 13.55, NULL),
  ('Marché central de Batouri', 'Étals débordant de plantains, poissons fumés, épices et pagnes, le marché de Batouri est un carnaval de couleurs et de saveurs de l''Est.', 'Est', 'CULTURE', 4.4335, 14.3675, NULL),
  ('Somalomo', 'Village d''accès nord à la réserve du Dja, Somalomo ouvre les sentiers vers la forêt classée et ses guides Baka et Badjoué.', 'Est', 'CULTURE', 3.38, 12.73, NULL),
  ('Palais du Lamido de Ngaoundéré', 'Joyau de l''architecture peule, ce palais aux cases sacrées et aux toits de chaume vous plonge dans la cour vivante d''un royaume séculaire.', 'Adamaoua', 'CHEFFERIE', 7.327, 13.584, 'https://commons.wikimedia.org/wiki/Special:FilePath/King''s_palace_Ngaoundere.PNG'),
  ('Grande Mosquée du Lamido de Ngaoundéré', 'Dressée au cœur de la cité, sa silhouette élégante résume des siècles de ferveur et de raffinement islamique sur le plateau de l''Adamaoua.', 'Adamaoua', 'RELIGIOUS', 7.323, 13.584, 'https://commons.wikimedia.org/wiki/Special:FilePath/LamidoGrandMosque.jpg'),
  ('Lac Tison', 'Niché dans un ancien cratère et bordé d''arbres, ce lac aux eaux paisibles est l''escapade nature favorite des Ngaoundéréens.', 'Adamaoua', 'NATURE', 7.25, 13.6, 'https://commons.wikimedia.org/wiki/Special:FilePath/Le_lac_de_cratère_de_Tizon_à_Ngaoundéré.jpg'),
  ('Lac de Mbalang', 'Miroir bleu posé dans un cratère volcanique, ce lac aux abords verdoyants invite à la baignade et à la rêverie loin de l''agitation.', 'Adamaoua', 'NATURE', 7.3, 13.73, NULL),
  ('Chutes de la Vina', 'Sur la rivière Vina, l''eau dévale les roches du plateau dans un fracas rafraîchissant, écrin sauvage aux portes de Ngaoundéré.', 'Adamaoua', 'NATURE', 7.1, 13.52, 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Madera_County_California_Incorporated_and_Unincorporated_areas_La_Vina_Highlighted_0640872.svg/960px-Madera_County_California_Incorporated_and_Unincorporated_areas_La_Vina_Highlighted_0640872.svg.png'),
  ('Chutes de Tello', 'Cascade spectaculaire jaillissant des hauteurs de l''Adamaoua, un rideau d''écume qui récompense les amateurs de randonnée.', 'Adamaoua', 'NATURE', 7.5, 13.5, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Chute_de_Tello_18.jpg/960px-Chute_de_Tello_18.jpg'),
  ('Chutes de Lancrenon', 'Parmi les plus majestueuses du pays, ces chutes vertigineuses plongent dans une gorge luxuriante près de la frontière orientale.', 'Adamaoua', 'NATURE', 7.1, 14.85, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Chutes_de_Lancrenon_%C3%A0_Yamba1.jpg/960px-Chutes_de_Lancrenon_%C3%A0_Yamba1.jpg'),
  ('Parc national du Mbam et Djerem', 'Vaste mosaïque de savanes et de forêts traversée de rivières, sanctuaire d''éléphants et de chimpanzés à la lisière de l''Adamaoua.', 'Adamaoua', 'NATURE', 5.75, 12.75, 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Cameroon_physical_map.svg/960px-Cameroon_physical_map.svg.png'),
  ('Lac et barrage de Mbakaou', 'Immense retenue d''eau aux reflets argentés près de Tibati, paradis des pêcheurs et des oiseaux migrateurs.', 'Adamaoua', 'NATURE', 6.33, 12.82, NULL),
  ('Ranch de Ngaoundaba', 'Entre lac de cratère et collines boisées, ce domaine paisible offre l''une des plus belles échappées vertes de l''Adamaoua.', 'Adamaoua', 'NATURE', 7.12, 13.73, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Le_lac_de_N%27Gaoundaba_pr%C3%A8s_de_Ngaound%C3%A9r%C3%A9.jpg/960px-Le_lac_de_N%27Gaoundaba_pr%C3%A8s_de_Ngaound%C3%A9r%C3%A9.jpg'),
  ('Palais du Lamido de Tibati', 'Témoin du puissant lamidat de Tibati, ce palais traditionnel garde la mémoire des cavaliers et des fêtes du Mbam.', 'Adamaoua', 'CHEFFERIE', 6.47, 12.63, NULL),
  ('Palais du Lamido de Banyo', 'Perché sur les hauts plateaux verdoyants, le palais de Banyo perpétue les fastes et les rites d''un vieux royaume peul.', 'Adamaoua', 'CHEFFERIE', 6.75, 11.82, NULL),
  ('Parc national de la Bénoué', 'Le long du fleuve Bénoué, hippopotames, antilopes et lions évoluent dans une savane dorée classée réserve de biosphère.', 'Nord', 'NATURE', 8.4, 13.83, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benoue_National_park_hippo.jpg'),
  ('Parc national de Bouba Ndjida', 'Joyau sauvage du Grand Nord, ce parc abrite éléphants, élands de Derby et babouins dans des paysages de brousse intacte.', 'Nord', 'NATURE', 8.67, 14.5, 'https://commons.wikimedia.org/wiki/Special:FilePath/Babouin_olive_(Papio_anubis)_au_Parc_National_de_Bouba_Ndjidda,_Cameroun.jpg'),
  ('Parc national du Faro', 'Aux confins de la frontière nigériane, ce sanctuaire reculé déroule des plaines giboyeuses où rôdent rhinocéros d''antan et grands fauves.', 'Nord', 'NATURE', 8.3, 12.75, 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Cameroon_physical_map.svg/960px-Cameroon_physical_map.svg.png'),
  ('Grand marché de Garoua', 'Carrefour bouillonnant du Nord, ses étals colorés mêlent cotonnades, épices et artisanat au rythme du fleuve Bénoué.', 'Nord', 'CULTURE', 9.3, 13.39, 'https://commons.wikimedia.org/wiki/Special:FilePath/Marche_Garoua_Nord_Cameroon.jpg'),
  ('Lac et barrage de Lagdo', 'Vaste mer intérieure née du fleuve Bénoué, ses rives offrent couchers de soleil flamboyants et poissons à profusion.', 'Nord', 'NATURE', 9.05, 13.73, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Lagdo_Dam.jpg/960px-Lagdo_Dam.jpg'),
  ('Palais du Lamido de Garoua', 'Résidence du chef traditionnel du Nord, ce palais incarne l''autorité et l''art de vivre peul sur les bords de la Bénoué.', 'Nord', 'CHEFFERIE', 9.3, 13.39, NULL),
  ('Lamidat de Rey Bouba', 'Cité-palais fortifiée et mystérieuse, Rey Bouba demeure l''un des plus puissants et secrets royaumes traditionnels du Cameroun.', 'Nord', 'CHEFFERIE', 8.67, 14.18, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Lamidat_de_Rey-Bouba_en_janvier_1974.jpg/960px-Lamidat_de_Rey-Bouba_en_janvier_1974.jpg'),
  ('Hosséré Vokré', 'Toit du Nord, ce massif granitique aux pentes abruptes domine la région de Poli et défie les randonneurs.', 'Nord', 'NATURE', 8.33, 12.87, NULL),
  ('Grande mosquée de Garoua', 'Repère spirituel de la capitale du Nord, ses minarets veillent sur une ville façonnée par l''islam et le négoce fluvial.', 'Nord', 'RELIGIOUS', 9.3, 13.4, 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Yaound%C3%A9_Palais_des_Congr%C3%A8s.jpg/960px-Yaound%C3%A9_Palais_des_Congr%C3%A8s.jpg'),
  ('Lamidat de Bibémi', 'Vieux royaume peul aux portes de Garoua, Bibémi conserve son palais de terre et ses traditions équestres.', 'Nord', 'CHEFFERIE', 9.31, 13.88, NULL),
  ('Parc national de Waza', 'Le plus célèbre safari du Cameroun, où éléphants, girafes et lions se rassemblent dans une savane d''acacias à perte de vue.', 'Extreme-Nord', 'NATURE', 11.32, 14.65, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bain_des_éléphants,_parc_de_Waza,_Nord_Cameroun_(25963018142).jpg'),
  ('Rhumsiki et le Pic de Kapsiki', 'Cathédrale de roche surgie d''un paysage quasi lunaire, Rhumsiki est le panorama le plus envoûtant des monts Mandara.', 'Extreme-Nord', 'NATURE', 10.53, 13.62, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhumsiki_peak,_North_Cameroon_(25989204581).jpg'),
  ('Monts Mandara', 'Chaîne volcanique aux pics déchiquetés et aux villages perchés en terrasses, royaume des montagnards Kapsiki et Mafa.', 'Extreme-Nord', 'NATURE', 10.7, 13.7, NULL),
  ('Village d''Oudjila', 'Accroché aux monts Mandara, ce village Podokwo séduit par ses cases en terre, sa chefferie et ses panoramas saisissants.', 'Extreme-Nord', 'CULTURE', 11.08, 14.17, NULL),
  ('Cases obus de Pouss', 'Sculptées en obus de terre par le peuple Mousgoum, ces demeures coniques sont un chef-d''œuvre d''architecture vernaculaire africaine.', 'Extreme-Nord', 'CULTURE', 10.85, 15.05, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cam0505_Habitation_de_Pouss_Case_obus.jpg'),
  ('Lac de Maga', 'Grand lac artificiel bordé de rizières et de pirogues, refuge d''innombrables oiseaux d''eau à l''extrême nord du pays.', 'Extreme-Nord', 'NATURE', 10.84, 14.95, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lac_de_Maga_dans_l''extrême_nord1.jpg'),
  ('Parc national de Kalamaloué', 'Petit parc giboyeux près de Kousséri, où éléphants et antilopes s''abreuvent aux bras du fleuve Chari.', 'Extreme-Nord', 'NATURE', 12.05, 14.93, NULL),
  ('Parc national de Mozogo-Gokoro', 'Îlot de forêt dense préservée au pied des monts Mandara, sanctuaire rare de biodiversité dans le Sahel.', 'Extreme-Nord', 'NATURE', 11.02, 13.95, NULL),
  ('Palais du Lamido de Maroua', 'Au cœur de la capitale du Diamaré, le palais résonne des tambours et des danses traditionnelles données en l''honneur du Lamido.', 'Extreme-Nord', 'CHEFFERIE', 10.59, 14.31, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danse_traditionnelle_chez_le_Lamido_de_Maroua.jpg'),
  ('Musée du Diamaré', 'À Maroua, ce musée raconte les peuples du Grand Nord à travers masques, parures et objets du quotidien sahélien.', 'Extreme-Nord', 'MUSEUM', 10.59, 14.32, NULL),
  ('Grand marché de Maroua', 'Temple de l''artisanat sahélien, on y déniche maroquinerie, bijoux et tissages dans un tourbillon de couleurs et de senteurs.', 'Extreme-Nord', 'CULTURE', 10.59, 14.32, 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/VUE_DE_MAROUA_DU_MONT_MAYO_IB%C3%89_%28EXTR%C3%8AME-NORD_CAMEROUN%29.jpg/960px-VUE_DE_MAROUA_DU_MONT_MAYO_IB%C3%89_%28EXTR%C3%8AME-NORD_CAMEROUN%29.jpg'),
  ('Dent de Mindif', 'Aiguille rocheuse dressée seule dans la plaine, ce pic spectaculaire attire grimpeurs et photographes près de Maroua.', 'Extreme-Nord', 'NATURE', 10.4, 14.45, 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Pic_Mindif3.jpg/960px-Pic_Mindif3.jpg'),
  ('Mokolo', 'Porte d''entrée des monts Mandara, cette cité animée vit au rythme des marchés montagnards et des fêtes Mafa.', 'Extreme-Nord', 'CULTURE', 10.74, 13.8, 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Zbi%C3%B3r_prosa_z_pola_-_Mokolo_-_001954s.jpg/960px-Zbi%C3%B3r_prosa_z_pola_-_Mokolo_-_001954s.jpg'),
  ('Marché de Mora', 'Célèbre marché hebdomadaire au pied des Mandara, point de rencontre haut en couleur des peuples Wandala et montagnards.', 'Extreme-Nord', 'CULTURE', 11.05, 14.14, 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Hotel_de_ville_de_Mora.jpg/960px-Hotel_de_ville_de_Mora.jpg'),
  ('Sultanat de Logone-Birni', 'Labyrinthe de murs de terre ocre, le palais des sultans Kotoko est un éblouissant témoignage d''architecture sahélienne.', 'Extreme-Nord', 'HERITAGE', 11.78, 15.08, NULL),
  ('Rive camerounaise du lac Tchad', 'Aux confins du pays, les eaux changeantes du lac Tchad nourrissent pêcheurs et oiseaux dans un paysage d''îles et de roseaux.', 'Extreme-Nord', 'NATURE', 12.55, 14.45, NULL),
  ('Village de cases de Yagoua', 'Terre du peuple Toupouri, Yagoua déploie ses cases de terre et ses fêtes de récolte au bord du Logone.', 'Extreme-Nord', 'CULTURE', 10.34, 15.23, 'https://commons.wikimedia.org/wiki/Special:FilePath/Village_de_Cases_Yagoua.jpg'),
  ('Tourou', 'Village des monts Mandara célèbre pour ses femmes coiffées de calebasses colorées, image emblématique du Grand Nord.', 'Extreme-Nord', 'CULTURE', 10.87, 13.63, NULL),
  ('Sultanat de Makari', 'Ancienne cité Kotoko proche du lac Tchad, Makari garde son palais et ses traditions de cavaliers du Sahel.', 'Extreme-Nord', 'CHEFFERIE', 12.58, 14.46, NULL),
  ('Grande mosquée de Maroua', 'Cœur spirituel de la cité sahélienne, ses minarets élancés veillent sur les ruelles ombragées de manguiers.', 'Extreme-Nord', 'RELIGIOUS', 10.59, 14.32, NULL),
  ('Kousséri', 'Ville-frontière posée sur le fleuve Chari face à N''Djamena, carrefour vivant des cultures du bassin du lac Tchad.', 'Extreme-Nord', 'CULTURE', 12.08, 15.03, NULL),
  ('Palais Royal des Rois Bamoun (Foumban)', 'Joyau de six siècles d''histoire, le palais des sultans Bamoun veille fièrement sur Foumban et son trône de perles.', 'Ouest', 'CHEFFERIE', 5.733, 10.9012, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bamun_sultan_palace.jpg'),
  ('Musée des Rois Bamoun (Foumban)', 'Plus de dix mille tresors royaux racontent l''epopee du royaume Bamoun dans un ecrin architectural spectaculaire.', 'Ouest', 'MUSEUM', 5.7285, 10.9005, NULL),
  ('Village des Artisans de Foumban', 'Bronziers, brodeurs et sculpteurs perpetuent le genie createur Bamoun le long de la celebre rue des artisans.', 'Ouest', 'CULTURE', 5.724, 10.895, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Sultanat_de_Foumban.JPG/960px-Sultanat_de_Foumban.JPG'),
  ('Festival Nguon (Foumban)', 'Tous les deux ans, le Nguon ressuscite des rites vieux de 600 ans ou le peuple juge meme son sultan.', 'Ouest', 'CULTURE', 5.729, 10.9, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Sultanat_de_Foumban.JPG/960px-Sultanat_de_Foumban.JPG'),
  ('Grande Mosquee de Foumban', 'Ses minarets elances dominent la cite Bamoun, coeur spirituel d''une ville musulmane a 80 pour cent.', 'Ouest', 'RELIGIOUS', 5.7268, 10.8985, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Sultanat_de_Foumban.JPG/960px-Sultanat_de_Foumban.JPG'),
  ('Chefferie Bandjoun', 'Cases a toits coniques et facades sculptees: la chefferie Bandjoun incarne toute la splendeur de l''art Bamileke.', 'Ouest', 'CHEFFERIE', 5.3667, 10.4167, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/La_r%C3%A9sidence_%28Renov%C3%A9e%29_de_l%27ancien_roi_Nie_KAMGA_Joseph_avant_dernier_chef_Bandjoun.JPG/960px-La_r%C3%A9sidence_%28Renov%C3%A9e%29_de_l%27ancien_roi_Nie_KAMGA_Joseph_avant_dernier_chef_Bandjoun.JPG'),
  ('Bandjoun Station (Musee d''art de Barthelemy Toguo)', 'Un centre d''art contemporain visionnaire ou la creation africaine dialogue avec le monde, signe Barthelemy Toguo.', 'Ouest', 'MUSEUM', 5.4, 10.42, NULL),
  ('Musee des Civilisations (Dschang)', 'Un voyage saisissant a travers les peuples du Cameroun, des Sawa aux Sahaliens, au coeur des montagnes de l''Ouest.', 'Ouest', 'MUSEUM', 5.447, 10.054, NULL),
  ('Festival Medumba (Bangangte)', 'Le pays Medumba celebre ses ancetres, sa langue et sa medecine traditionnelle dans une explosion de couleurs.', 'Ouest', 'CULTURE', 5.15, 10.52, NULL),
  ('Chefferie Bana', 'Perchee sur les hauteurs, la chefferie Bana garde ses totems et ses cases royales aux portes finement sculptees.', 'Ouest', 'CHEFFERIE', 5.13, 10.3, NULL),
  ('Chefferie de Bafut', 'Sanctuaire Achum et foret sacree: la chefferie Bafut, joyau classe, fait revivre la cour vivante du Fon.', 'Nord-Ouest', 'CHEFFERIE', 6.1, 10.1, NULL),
  ('Musee de Babungo (Ndop)', 'Dans l''ancien grand centre de forge du Cameroun, un musee communautaire devoile masques, bronzes et savoir-faire ancestraux.', 'Nord-Ouest', 'MUSEUM', 6.0715, 10.4423, NULL),
  ('Palais des Fons de Nso (Kumbo)', 'Au coeur des Grassfields, le palais du Fon de Nso veille sur l''un des plus puissants royaumes du Nord-Ouest.', 'Nord-Ouest', 'CHEFFERIE', 6.205, 10.67, 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Tobin_View_of_the_Cathedral.JPG/960px-Tobin_View_of_the_Cathedral.JPG'),
  ('Festival Ngonnso (Kumbo)', 'Le peuple Nso honore sa reine fondatrice Ngonnso dans un festival vibrant de tambours, danses et fierte ancestrale.', 'Nord-Ouest', 'CULTURE', 6.2, 10.67, NULL),
  ('Cathedrale metropolitaine Saint-Joseph de Bamenda', 'Dressee sur les collines de Bamenda, la cathedrale Saint-Joseph veille sur la capitale des Grassfields.', 'Nord-Ouest', 'RELIGIOUS', 5.96, 10.15, NULL),
  ('Festival Ngondo (Douala)', 'Chaque decembre, les peuples Sawa rendent hommage au fleuve Wouri lors d''une plongee mystique au pays des eaux.', 'Littoral', 'CULTURE', 4.0469, 9.69, NULL),
  ('La Nouvelle Liberte (Douala)', 'Geant de douze metres ne de la ferraille recyclee, ce chef-d''oeuvre de Sumegne incarne l''energie creative de Douala.', 'Littoral', 'HERITAGE', 4.0593, 9.7344, 'https://commons.wikimedia.org/wiki/Special:FilePath/Statue_de_la_nouvelle_liberte_Douala.jpg'),
  ('Cathedrale Saints-Pierre-et-Paul de Douala', 'Edifice emblematique du Littoral, la cathedrale de Douala marie ferveur catholique et memoire coloniale.', 'Littoral', 'RELIGIOUS', 4.049, 9.696, NULL),
  ('La Pagode - Palais des Rois Bell (Douala)', 'Curiosite architecturale aux airs d''Asie, l''ancien palais du roi Manga Bell raconte l''histoire des cotes Douala.', 'Littoral', 'HERITAGE', 4.048, 9.692, NULL),
  ('Espace doual''art', 'Pionnier de l''art contemporain africain, doual''art transforme la ville en galerie a ciel ouvert.', 'Littoral', 'CULTURE', 4.05, 9.695, NULL),
  ('Festival Mpo''o (Edea)', 'Le peuple Bassa celebre ses origines et son identite lors du Mpo''o, grand rendez-vous culturel d''Edea.', 'Littoral', 'CULTURE', 3.8, 10.133, NULL),
  ('Monument de la Reunification (Yaounde)', 'Spirale audacieuse de Mveng et Mpando, ce monument celebre l''union des deux Cameroun en un seul peuple.', 'Centre', 'HERITAGE', 3.8525, 11.5134, NULL),
  ('Basilique Marie-Reine-des-Apotres de Mvolye (Yaounde)', 'Sur la colline de Mvolye, l''une des plus grandes basiliques d''Afrique accueille des milliers de pelerins.', 'Centre', 'RELIGIOUS', 3.8425, 11.5078, 'https://commons.wikimedia.org/wiki/Special:FilePath/Int%C3%A9rieur_Basilique_Marie-Reine_des_ap%C3%B4tres_de_Mvoly%C3%A9_2.jpg'),
  ('Musee National du Cameroun (Yaounde)', 'Dans l''ancien palais presidentiel, le Musee National deroule l''histoire et les arts de tout le pays.', 'Centre', 'MUSEUM', 3.858, 11.517, NULL),
  ('Cathedrale Notre-Dame-des-Victoires (Yaounde)', 'Cathedrale historique de la capitale, Notre-Dame-des-Victoires domine le centre-ville de ses tours elancees.', 'Centre', 'RELIGIOUS', 3.866, 11.518, 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Cath%C3%A9drale_Notre-Dame_Yaound%C3%A9.jpg/960px-Cath%C3%A9drale_Notre-Dame_Yaound%C3%A9.jpg'),
  ('Musee d''Art Camerounais (Mont Febe, Yaounde)', 'Niche sur le mont Febe, ce musee benedictin abrite une exceptionnelle collection de masques et bronzes.', 'Centre', 'MUSEUM', 3.905, 11.495, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/B%C3%A2timent_du_mus%C3%A9e_des_B%C3%A9n%C3%A9dictins.jpg/960px-B%C3%A2timent_du_mus%C3%A9e_des_B%C3%A9n%C3%A9dictins.jpg'),
  ('Ngog Lituba (rocher sacre Bassa)', 'Berceau mythique des peuples Bassa, Mpoo et Bati, ce rocher perce est un lieu de memoire et de pelerinage.', 'Centre', 'HERITAGE', 3.92, 10.85, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Coucher_de_soleil_%C3%A0_Tayap.JPG/960px-Coucher_de_soleil_%C3%A0_Tayap.JPG'),
  ('Ancien Palais du Gouverneur allemand (Buea)', 'Au pied du mont Cameroun, l''ancienne residence du gouverneur allemand temoigne du passe colonial de Buea.', 'Sud-Ouest', 'HERITAGE', 4.155, 9.24, 'https://upload.wikimedia.org/wikipedia/commons/0/0f/Silicon_Mountain_as_seen_in_Buea%2C_Cameroon_on_26-06-2019.jpg'),
  ('Memorial du port negrier de Bimbia', 'Site national de memoire, Bimbia conserve la bouleversante Porte du non-retour de la traite negriere.', 'Sud-Ouest', 'HERITAGE', 3.9833, 9.305, NULL),
  ('Mount Cameroon Race of Hope (Buea)', 'Course mythique vers le toit de l''Afrique de l''Ouest, la Race of Hope defie chaque annee le mont Cameroun.', 'Sud-Ouest', 'CULTURE', 4.16, 9.23, NULL),
  ('Palais du Lamido de Ngaoundere', 'Joyau de l''Adamaoua, le palais du Lamido de Ngaoundere accueille le visiteur au son des tambours royaux.', 'Adamaoua', 'CHEFFERIE', 7.327, 13.584, NULL),
  ('Festival Nyem-Nyem (Galim)', 'Au pied du mont Djim, le peuple Nyem-Nyem commemore sa resistance heroique a l''occupant lors d''un festival fervent.', 'Adamaoua', 'CULTURE', 7.13, 12.5, NULL),
  ('Musee du Diamare (Maroua)', 'Fonde en 1955, le musee du Diamare reunit l''art et l''ethnographie des peuples de l''Extreme-Nord.', 'Extreme-Nord', 'MUSEUM', 10.595, 14.315, NULL),
  ('Grande Mosquee de Maroua', 'Au coeur de la cite sahelienne, la grande mosquee de Maroua rythme la vie spirituelle de la capitale du Diamare.', 'Extreme-Nord', 'RELIGIOUS', 10.591, 14.32, NULL),
  ('Cathedrale Sainte-Anne-et-Saint-Joachim d''Ebolowa', 'Edifice majeur du Sud, la cathedrale d''Ebolowa rassemble les fideles au coeur du pays Bulu.', 'Sud', 'RELIGIOUS', 2.915, 11.154, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Cath%C3%A9drale_d%27Abang.jpg/960px-Cath%C3%A9drale_d%27Abang.jpg'),
  ('Villages Baka de Lomie', 'A la lisiere de la grande foret, les communautes Baka partagent chants polyphoniques, danses et savoirs de la jungle.', 'Est', 'CULTURE', 3.15, 13.62, 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Lomi%C3%A9_crossroads.jpg/960px-Lomi%C3%A9_crossroads.jpg'),
  ('Cathedrale du Sacre-Coeur de Bertoua', 'Principal sanctuaire de l''Est forestier, la cathedrale de Bertoua veille sur la capitale regionale.', 'Est', 'RELIGIOUS', 4.577, 13.684, NULL),
  ('id', 'name', 'description', 'region', NULL, NULL, 'longitude')
)
INSERT INTO tourism_places
  (id, name, description, region, category, latitude, longitude, image_url, source, source_ref,
   verified, verified_by_account_id, submitted_by_account_id, visibility_scope, created_at, updated_at)
SELECT
  uuid_generate_v4(), d.name, d.description, d.region,
  d.category::"tourism_category", d.lat, d.lng, d.image_url, 'COMMUNITY'::"tourism_source",
  'Recherché sur des sources publiques (Wikipedia, Wikimedia Commons)',
  TRUE, (SELECT id FROM admin), (SELECT id FROM admin), 'PUBLIC'::"visibility_scope", NOW(), NOW()
FROM data d
WHERE NOT EXISTS (SELECT 1 FROM tourism_places t WHERE lower(t.name) = lower(d.name));

